"""Render paired preprocessor timing and allocation results as standalone HTML."""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]
directory = ROOT / 'suite/reports'
timing = json.loads((directory / 'c-preprocessor-optimized-20261015.json').read_text())
allocations = json.loads((directory / 'c-preprocessor-allocations-20261015.json').read_text())
style = (directory / 'c-frontend-profile-20261015.html').read_text().split('<style>', 1)[1].split('</style>', 1)[0]
data = {'timing': timing['summaries'], 'aggregate': timing['aggregate'], 'allocations': allocations['applications']}
html = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Preprocessor optimization results</title><style>__STYLE__
.bargroup{margin:16px 0 22px}.bargroup b{display:block;margin-bottom:6px}.barline{display:grid;grid-template-columns:100px 1fr 70px;gap:8px;align-items:center;margin:5px 0;font-size:12px}.barline .track,.barline .segment{height:17px}.barline span:last-child{text-align:right;font-variant-numeric:tabular-nums}.change{font-size:13px;margin:9px 0}.change code{font-size:12px}.ok{color:var(--success,#42a57a)}@media(max-width:450px){.barline{grid-template-columns:86px 1fr 62px;gap:5px;font-size:11px}.stats{gap:6px}.stat strong{font-size:19px}}
</style></head><body>
<h2>Preprocessing is 2.44× faster</h2>
<p class="meta muted">Apple M5 Max · local main ae7c2f8 → working-tree optimization · release + symbols · 15 Oct 2026</p>
<p class="lead">Allocation and copying reductions deliver most of the improvement. SIMD-backed searches contribute a further <strong>4.6–5.1% less time</strong> over the compact scalar implementation.</p>
<div class="stats"><div class="stat"><strong>59% less</strong><span>preprocessing time, equal-app geometric mean</span></div><div class="stat"><strong>76–77%</strong><span>fewer allocator calls, including reallocations</span></div><div class="stat"><strong>44 / 44</strong><span>byte-identical preprocessed application files</span></div></div>
<div class="controls"><button id="absolute" class="active" onclick="setRelative(false)">Milliseconds</button><button id="relative" onclick="setRelative(true)">Relative to original</button></div>
<div class="legend"><span class="key" style="--c:#939aa7">Original</span><span class="key" style="--c:#4d9ed6">Compact scalar</span><span class="key" style="--c:#46aa93">Compact + SIMD</span></div>
<div id="bars" aria-label="Original versus compact scalar and SIMD preprocessing"></div>
<div class="tablewrap"><table><thead><tr><th>Application</th><th>Original ms</th><th>Optimized ms</th><th>Paired speedup</th><th>95% interval</th><th>SIMD increment</th></tr></thead><tbody id="timings"></tbody></table></div>
<p class="note">Eleven paired rounds, serial application batches. Times are medians; speedup uses the median of same-round time ratios, so it may differ from dividing the displayed medians. Intervals bootstrap paired ratios.</p>
<h3>What changed</h3>
<div class="finding"><p class="change"><strong>Less allocation:</strong> each file path is reference-counted once; macro definitions are shared; ordinary tokens get one text allocation instead of up to three. Tokens move between line processing and expansion instead of being copied.</p><p class="change"><strong>Less scanning state:</strong> borrowed input when there are no splices, sparse splice events and streaming physical locations replace the per-byte location table and second byte buffer.</p><p class="change"><strong>Fewer comparisons:</strong> punctuation dispatches by its first byte; expansion skips punctuation, numbers and ordinary identifiers before cloning or constructing replacement tokens.</p><p class="change"><strong>Portable SIMD:</strong> bounded <code>memchr</code>, <code>memchr3</code> and substring searches scan line splices, comments, literal delimiters and newlines. The dependency supplies architecture dispatch and scalar tails; production code adds no unsafe loads.</p></div>
<h3>Allocation counts confirm the mechanism</h3>
<div class="tablewrap"><table><thead><tr><th>Application</th><th>Original calls</th><th>Optimized calls</th><th>Fewer calls</th><th>Fewer requested bytes</th></tr></thead><tbody id="allocations"></tbody></table></div>
<p class="note">Calls include allocation and reallocation. Requested bytes are cumulative allocation requests, including full new reallocation sizes; they are not peak memory or RSS. Counts use separate instrumented binaries that were never timed.</p>
<p><strong class="ok">57 tests pass.</strong> All three timing variants produce byte-identical output on every Lua, QuickJS and SQLite translation unit, and every output compiles to verified IR. New regressions cover LF/CRLF and adjacent splices, physical diagnostic locations, UTF-8, digraphs, and delimiters across SIMD boundaries.</p>
<details><summary>Method and limits</summary><ul><li>Lua 5.4.7: 33 translation units; QuickJS 2024-01-13 with BigNum: 9; SQLite 3.46.1 + shell: 2. Same sources, defines, SDK and header search paths in every variant.</li><li>Original and candidate binaries are immutable copies built before timing. Measurements are warm-cache library calls with top-level sources resident. Transitive header IO, expansion, formatting and internal destruction are included. Startup, top-level input reading, SDK discovery and returned-text destruction are excluded.</li><li>Applications are shuffled in each of eleven rounds; the three variants rotate execution order. Each process warms the whole application before measurement. Baseline medians are freshly measured in these same rounds.</li><li>The compact-scalar variant has the same runtime implementation as the final version except its three search helpers use scalar loops. The exact source patch and hashes are retained, isolating the SIMD search contribution.</li><li>Timing and allocation measurements are independent. The allocation example uses an identical TLS counting allocator with the original and optimized implementations, enabled only during preprocessing.</li><li>The full C frontend test suite passes (50 tests), plus the compiler driver's preprocessing integration suite (7). Formatting and diff checks pass.</li><li>Geometric means weight each of the three applications equally. Bootstrap intervals describe variation on this fixed corpus. SIMD measurements are from Apple M5 Max; other CPUs and cold builds have not been timed. This report measures preprocessing, not complete compilation or executable runtime.</li></ul></details>
<p class="foot">Source/build hashes, the scalar ablation patch, raw paired timings, allocation counts and reproduction commands are saved in suite/reports and suite/README.md.</p>
<script>const D=__DATA__;const apps=['lua','quickjs','sqlite'];const labels={lua:'Lua',quickjs:'QuickJS',sqlite:'SQLite'};const variants=['baseline','compact-scalar','simd'];const names=['Original','Compact scalar','Compact + SIMD'];const colors=['#939aa7','#4d9ed6','#46aa93'];let relative=false;const fmt=n=>n.toFixed(1);function setRelative(x){relative=x;draw()}function draw(){document.getElementById('absolute').classList.toggle('active',!relative);document.getElementById('relative').classList.toggle('active',relative);const max=relative?1:Math.max(...apps.map(a=>D.timing[a].median_ms.baseline));document.getElementById('bars').innerHTML=apps.map(a=>{const s=D.timing[a];return`<div class="bargroup"><b>${labels[a]}</b>${variants.map((v,i)=>{const time=s.median_ms[v];const value=relative?time/s.median_ms.baseline:time;return`<div class="barline"><span>${names[i]}</span><div class="track"><div class="segment" style="background:${colors[i]};width:${100*value/max}%" title="${labels[a]} ${names[i]}: ${fmt(time)} ms"></div></div><span>${relative?fmt(value*100)+'%':fmt(time)+' ms'}</span></div>`}).join('')}</div>`}).join('');document.getElementById('timings').innerHTML=apps.map(a=>{const s=D.timing[a],c=s.comparisons.simd;return`<tr><td>${labels[a]}</td><td>${fmt(s.median_ms.baseline)}</td><td><strong>${fmt(s.median_ms.simd)}</strong></td><td><strong>${c.speedup.toFixed(2)}×</strong></td><td>${(1/c.ratio_ci95[1]).toFixed(2)}–${(1/c.ratio_ci95[0]).toFixed(2)}×</td><td>${fmt((1-s.simd_vs_scalar.median_ratio)*100)}% less time</td></tr>`}).join('');document.getElementById('allocations').innerHTML=apps.map(a=>{const s=D.allocations[a],b=s.baseline.totals,c=s.candidate.totals;return`<tr><td>${labels[a]}</td><td>${((b.alloc+b.realloc)/1e6).toFixed(2)}M</td><td>${((c.alloc+c.realloc)/1e6).toFixed(2)}M</td><td><strong>${fmt(s.allocation_call_reduction*100)}%</strong></td><td>${fmt(s.requested_bytes_reduction*100)}%</td></tr>`}).join('')}draw();console.log('Rendered three applications, eleven timing pairs and independent allocation counts');</script></body></html>'''
html = html.replace('__STYLE__', style).replace('__DATA__', json.dumps(data, separators=(',', ':')))
output = directory / 'c-preprocessor-optimized-20261015.html'
output.write_text(html)
print(output)
